#!/usr/bin/env bash
# Adds a "Dev Files" area (platform admins only) for browsing, editing,
# and downloading the source files shipped to every kiosk: agent/,
# service_files/, and requirements.txt — exactly what
# app/static/installers/opslab-agent.tar.gz is built from.
#
# Features:
#   - Browse + edit files in a web textarea, save writes straight to disk.
#   - Every save is logged (audit trail) and snapshotted to
#     data/dev_file_backups/ before being overwritten.
#   - Download any single file, or the whole thing as one .zip.
#   - "Publish" button rebuilds opslab-agent.tar.gz from whatever's
#     currently on disk — the same tar/gzip that's been done by hand all
#     session, now one click. New installs pick it up immediately;
#     already-enrolled kiosks still need a reinstall (no remote Agent
#     self-update channel exists — same caveat as every earlier
#     agent-side push).
#
# Restricted to platform admins (is_platform_admin) since these files
# affect every company's kiosks, not one — same trust boundary as
# uploading a release package. Path-traversal-protected: only agent/,
# service_files/, and requirements.txt are reachable, verified via
# os.path.realpath + strict prefix checks, tested against '../', absolute
# paths, and symlink escapes before this was shipped.
#
# No database migration in this push.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in app agent requirements.txt run.py; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

TS="$(date +%Y%m%d_%H%M%S)"
mkdir -p "backups/$TS/templates/dev_files"
cp app/__init__.py "backups/$TS/__init__.py.bak" 2>/dev/null || true
cp app/templates/base.html "backups/$TS/templates/base.html.bak" 2>/dev/null || true
echo "==> Backed up existing files to backups/$TS/"

mkdir -p app/templates/dev_files

echo "==> Writing app/__init__.py"
base64 -d > app/__init__.py << 'INIT_PY_B64'

INIT_PY_B64

echo "==> Writing app/blueprints/dev_files.py (new)"
base64 -d > app/blueprints/dev_files.py << 'DEV_FILES_PY_B64'

DEV_FILES_PY_B64

echo "==> Writing app/templates/base.html"
base64 -d > app/templates/base.html << 'BASE_HTML_B64'

BASE_HTML_B64

echo "==> Writing app/templates/dev_files/index.html (new)"
base64 -d > app/templates/dev_files/index.html << 'DEV_INDEX_HTML_B64'

DEV_INDEX_HTML_B64

echo "==> Writing app/templates/dev_files/edit.html (new)"
base64 -d > app/templates/dev_files/edit.html << 'DEV_EDIT_HTML_B64'

DEV_EDIT_HTML_B64

echo "==> Verifying"
python3 -c "import ast; ast.parse(open('app/__init__.py').read())"
python3 -c "import ast; ast.parse(open('app/blueprints/dev_files.py').read())"
echo "    all Python files: syntax OK"

echo ""
echo "==> Restarting the admin panel app"
pkill -f "admin_panel/run.py" 2>/dev/null || true
fuser -k 6090/tcp 2>/dev/null || true
sleep 1
source venv/bin/activate
nohup python run.py > app.log 2>&1 &
disown
sleep 2
tail -n 15 app.log

echo ""
echo "==================================================================="
echo "Dev Files live at /admin/dev-files (platform admins only, in the"
echo "sidebar under Platform)."
echo "  - Browse and edit agent/, service_files/, requirements.txt."
echo "  - Every save is logged + snapshotted to data/dev_file_backups/."
echo "  - Download a file, or everything as one .zip."
echo "  - 'Publish' rebuilds opslab-agent.tar.gz for new installs — it"
echo "    does NOT reach already-enrolled kiosks; those need a reinstall."
echo "==================================================================="
